+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Snake Game</title>
+    <style>
+        body {
+            display: flex;
+            justify-content: center;
+            align-items: center;
+            min-height: 100vh;
+            margin: 0;
+            padding: 20px;
+            background: #090d16;
+        }
+        .game-container {
+            background: rgba(16, 24, 40, 0.75);
+            backdrop-filter: blur(20px);
+            padding: 20px;
+            border-radius: 10px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+        }
+        .game-header {
+            display: flex;
+            justify-content: space-between;
+            padding: 12px 20px;
+        }
+        .score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+        .high-score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+        .start-game-overlay {
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            display: flex;
+            justify-content: center;
+            align-items: center;
+            flex-direction: column;
+        }
+        .start-game-button {
+            background: #34A8FF;
+            color: #fff;
+            padding: 10px 20px;
+            border: none;
+            border-radius: 5px;
+            cursor: pointer;
+        }
+        .game-over-overlay {
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            display: none;
+            justify-content: center;
+            align-items: center;
+            flex-direction: column;
+        }
+        .game-over-button {
+            background: #34A8FF;
+            color: #fff;
+            padding: 10px 20px;
+            border: none;
+            border-radius: 5px;
+            cursor: pointer;
+        }
+        .canvas-container {
+            width: 400px;
+            height: 400px;
+            border: 1px solid #fff;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <div class="game-header">
+            <span class="score">Score: 0</span>
+            <span class="high-score">High Score: 0</span>
+        </div>
+        <div class="start-game-overlay">
+            <h1>Snake Game</h1>
+            <button class="start-game-button" id="start-game-button">Play</button>
+        </div>
+        <div class="game-over-overlay">
+            <h1>Game Over</h1>
+            <button class="game-over-button" id="game-over-button">Replay</button>
+        </div>
+        <div class="canvas-container">
+            <canvas id="game-canvas" width="400" height="400"></canvas>
+        </div>
+    </div>
+    <script>
+        let score = 0;
+        let highScore = 0;
+        let snake = [];
+        let food = null;
+        let direction = 'right';
+        let gameInterval = null;
+        let gameOver = false;
+        const canvas = document.getElementById('game-canvas');
+        const ctx = canvas.getContext('2d');
+        const startGameButton = document.getElementById('start-game-button');
+        const gameOverButton = document.getElementById('game-over-button');
+        const startGameOverlay = document.querySelector('.start-game-overlay');
+        const gameOverOverlay = document.querySelector('.game-over-overlay');
+        const scoreSpan = document.querySelector('.score');
+        const highScoreSpan = document.querySelector('.high-score');
+        
+        startGameButton.addEventListener('click', startGame);
+        gameOverButton.addEventListener('click', restartGame);
+        
+        function startGame() {
+            startGameOverlay.style.display = 'none';
+            score = 0;
+            highScore = parseInt(localStorage.getItem('highScore')) || 0;
+            snake = [
+                { x: 200, y: 200 },
+                { x: 190, y: 200 },
+                { x: 180, y: 200 }
+            ];
+            food = generateFood();
+            direction = 'right';
+            gameInterval = setInterval(update, 100);
+        }
+        
+        function restartGame() {
+            gameOverOverlay.style.display = 'none';
+            startGame();
+        }
+        
+        function update() {
+            if (gameOver) return;
+            ctx.clearRect(0, 0, canvas.width, canvas.height);
+            drawSnake();
+            drawFood();
+            moveSnake();
+            checkCollision();
+            updateScore();
+        }
+        
+        function drawSnake() {
+            snake.forEach((segment) => {
+                ctx.fillStyle = 'green';
+                ctx.fillRect(segment.x, segment.y, 10, 10);
+            });
+        }
+        
+        function drawFood() {
+            ctx.fillStyle = 'red';
+            ctx.fillRect(food.x, food.y, 10, 10);
+        }
+        
+        function moveSnake() {
+            const head = snake[0];
+            let newHead = null;
+            switch (direction) {
+                case 'right':
+                    newHead = { x: head.x + 10, y: head.y };
+                    break;
+                case 'left':
+                    newHead = { x: head.x - 10, y: head.y };
+                    break;
+                case 'up':
+                    newHead = { x: head.x, y: head.y - 10 };
+                    break;
+                case 'down':
+                    newHead = { x: head.x, y: head.y + 10 };
+                    break;
+            }
+            snake.unshift(newHead);
+            if (snake[0].x === food.x && snake[0].y === food.y) {
+                food = generateFood();
+            } else {
+                snake.pop();
+            }
+        }
+        
+        function checkCollision() {
+            const head = snake[0];
+            if (head.x < 0 || head.x >= canvas.width || head.y < 0 || head.y >= canvas.height) {
+                gameOver = true;
+            }
+            for (let i = 1; i < snake.length; i++) {
+                if (head.x === snake[i].x && head.y === snake[i].y) {
+                    gameOver = true;
+                }
+            }
+            if (gameOver) {
+                gameOverOverlay.style.display = 'flex';
+                if (score > highScore) {
+                    highScore = score;
+                    localStorage.setItem('highScore', highScore);
+                }
+            }
+        }
+        
+        function updateScore() {
+            scoreSpan.textContent = `Score: ${score}`;
+            highScoreSpan.textContent = `High Score: ${highScore}`;
+            score++;
+        }
+        
+        function generateFood() {
+            const x = Math.floor(Math.random() * (canvas.width / 10)) * 10;
+            const y = Math.floor(Math.random() * (canvas.height / 10)) * 10;
+            return { x, y };
+        }
+        
+        document.addEventListener('keydown', (e) => {
+            switch (e.key) {
+                case 'ArrowUp':
+                    if (direction !== 'down') direction = 'up';
+                    break;
+                case 'ArrowDown':
+                    if (direction !== 'up') direction = 'down';
+                    break;
+                case 'ArrowLeft':
+                    if (direction !== 'right') direction = 'left';
+                    break;
+                case 'ArrowRight':
+                    if (direction !== 'left') direction = 'right';
+                    break;
+            }
+        });
+    </script>
+</body>
+</html>

